-- 40 · statutory_parameters for GST on TaxWise's own invoices (§6.4) and TDS deducted by clients on
-- TaxWise's fees (§6.5). §16 content only: law and firm-practice parameters, no clients, no users,
-- no demo data. Settled law is seeded verified = true; [verify] items verified = false, so the
-- Law & rules page lists them as "awaiting partner confirmation" (§6, §7.21).
--
-- Idempotent: on conflict (key, effective_from) do nothing, so re-running never overwrites a value
-- or a verification a Partner has since recorded. Amounts inside values are in RUPEES.
-- The same rows live in lib/domain/gst.ts (GST_SEED_PARAMETERS) and lib/domain/tds.ts
-- (TDS_SEED_PARAMETERS); tests/unit/gst.test.ts checks that this file matches them.
--
-- Keys (exported as GST_PARAM_KEYS / TDS_PARAM_KEYS / TDS_BASE_PARAM_KEY):
--   GST (lib/domain/gst.ts)
--   gst.default_rate_services     number, GST % for SAC group 9982 (18). From 22 Sep 2025 [verify].
--   gst.slabs                     number[], the slab structure ([0,5,18,40] from 22 Sep 2025).
--   gst.invoice_rate_options      {"options":[18,5,0],"allowOther":true}: the invoice rate picker.
--   gst.sac_by_service            {"default":"9982","byService":{service_type: SAC}}: default SAC map
--                                 (firm_settings.sac_by_service is the editable copy). Confirm with partners.
--   gst.sac_digits                {"turnoverUpTo":50000000,"digitsUpTo":4,"digitsAbove":6} (Rule 46).
--   gst.e_invoicing_threshold     {"amount":50000000}: e-invoicing above ₹5 crore aggregate turnover.
--   gst.e_invoice_reporting_window {"amount":100000000,"days":30}: IRP 30-day limit from ₹10 crore.
--   gst.b2c_address_threshold     {"amount":50000,"inclusive":false}: unregistered recipient's address
--                                 and state above this invoice value (Rule 46(f)) [verify > vs ≥].
--   gst.invoice_issue_days        number, 30: invoice within 30 days of supply (Rule 47).
--   gst.unbilled_flag_days        number, 25: flag completed unbilled work after 25 days.
--   gst.credit_note_deadline      {"month":11,"day":30}: s.34(2) deadline after the FY of supply.
--   gst.credit_note_warn_days     number, 30: warn this many days before the s.34 deadline.
--   TDS (lib/domain/tds.ts); looked up by PAYMENT date: 1961 Act rows end 31 Mar 2026, s.393 rows
--   (Income-tax Act, 2025) start 1 Apr 2026 [verify].
--   tds.base_excludes_gst         true: TDS on the fee excluding GST shown separately (Circular 23/2017).
--   tds.<nature>.rate             {"rate": %, "section": "194J"|"194C"|"194H"|"194I"|"393"}
--   tds.<nature>.threshold        {"amount": ₹, "per": "year"|"month"|"payment"[, "annual": ₹]}
--     natures: professional_fees, technical_services, commission, rent_land_building,
--              rent_plant_machinery, contract_individual_huf, contract_others

insert into public.statutory_parameters
  (key, value, effective_from, effective_to, statute, section_ref, source_ref, notes, verified)
